class CommandExecutionList(list):
    def first(self):
        return self[0]


class Validators(object):
    def __init__(self, *validators):
        self._validators = list(validators)

    def add(self, validator):
        self._validators.append(validator)

    def clean(self):
        self._validators = []

    def all(self):
        return self._validators

    def validate(self, command_result):
        return CommandExecutionList([validator.validate(command_result) for validator in self._validators])
